B=[['拉丁 bi-；bis；bini','两、双；两次；两个一组']]
BIN=B+[['晚期拉丁 binarius → 中古英语 binarie → binary','由两个组成的、成双的'],['现代 binary','二元的；二进制的；也作相关名词']]
EYE=B+[['拉丁 bini + ocularis；法语 binoculaire','两个一起 + 眼睛的 → 双眼的'],['英语 binocular','涉及双眼的；也用于双目光学仪器']]
GAM=B+[['晚期拉丁 bigamus → bigamia','bi- 与希腊 gamos“婚姻”结合 → 两次婚姻、重婚'],['古法语／盎格鲁法语 bigamie → 中古英语 bigamie → bigamy','旧义范围较宽；现代通常指婚姻仍存续时另行结婚']]
COOK=B+[['拉丁 bis + coctus → 中世纪拉丁 biscoctus／biscoctum','两次 + 烤熟的 → 烤两次的面食']]
PART=B+[['英语 bi- + partisan → bipartisan','两党参与或支持的'],['现代政治用法','跨越两个政党立场的合作、支持']]
LAT=B+[['拉丁 latus、lateris → lateralis；法语 latéral／英语 lateral','侧面 → 侧面的'],['英语 bi- + lateral → bilateral','两侧的；涉及双方的']]
FUR=B+[['拉丁 bi- + furca → bifurcus','两 + 叉子 → 分成两叉的'],['中世纪拉丁 bifurcare；分词 bifurcatus → 英语 bifurcate','分成两个分支']]
LAW='https://www.law.cornell.edu/wex/bigamy'
W=[
E('binary','英、美 /ˈbaɪnəri/','二元的；由两部分组成的；二进制的；二进制数据或程序','先把东西放进只有两个基本类别或状态的框架。计算机里常用 0 和 1 表示这两种状态；生活里则可能是把事情分成“是或否”。','借晚期拉丁 binarius“成双、由两个组成的”，经中古英语 binarie 形成 binary。bini 是“两个一组”；现代可辨 bin- + -ary，但整词不是计算机时代才造出来的。',BIN,'binary numbers 用二进制记数，例如十进制的 2 写作 10。a binary choice 常只有两个选项；a binary file 是二进制文件。天文中的 binary star 是双星，也保留“两成员”的意思。','a binary choice；binary code；a binary number；a binary file；a binary star。','binary 不等于“里面只有两个东西”：二进制数可以很长，只是每一位使用两种数字。a binary choice 也不意味着现实一定只有两种可能。',('The program stores the result in a binary file.','程序把结果存入一个二进制文件。'),('The survey reduced a complicated issue to a binary choice.','这份调查把复杂问题缩成了二选一。'),sources=[S('binary'),K('binary'),O('binary')]),
E('nonbinary','英 /ˌnɒnˈbaɪnəri/；美 /ˌnɑːnˈbaɪnəri/','非二元的；非二进制的；非二元性别的','不把某件事完全框进两个互斥格子里。用于性别时，指一个人的性别认同不完全落在“男性或女性”这个二分框架中。','英语 non-“非、不” + binary。一般“不只由两部分组成”的用法较早；性别认同用法是后来的专门发展，不能把早期技术记录误当成现代性别用法的起点。',BIN[:2]+[['英语 non- + binary → nonbinary','非二元、非二进制的'],['后来的性别用法','不完全以男性／女性二分界定的性别认同']],'nonbinary person 是非二元性别者；它讲性别认同，不说明一个人被什么性别的人吸引，也不规定所有人使用同一套代词。数学、计算等语境仍可能只是在谈非二元结构。','a nonbinary person；nonbinary gender identities；a nonbinary system。','bisexual 主要谈性取向；nonbinary 的常见现代用法谈性别认同，两者不是同一问题。',('The profile describes Alex as a nonbinary writer.','人物介绍说，Alex 是一位非二元性别作家。'),('The paper compares binary and nonbinary coding schemes.','论文比较了二元和非二元编码方案。'),sources=[M('nonbinary'),O('non-binary'),K('nonbinary'),S('binary')]),
E('binocular','英 /bɪˈnɒkjələ/；美 /bɪˈnɑːkjələr/','双眼的；双目的','两只眼睛一起参与，而不是只靠一只眼。两个稍有差别的视角可以被大脑结合起来，帮助判断空间。','常见来源分析为法语 binoculaire 借入，以拉丁 bini“两个一起”与 ocularis“眼睛的”为基础；也有按 bini + oculus、仿 ocular 解释的词典。不是 bin“箱子” + ocular。',EYE,'binocular vision 是双眼视觉；a binocular microscope 是双目显微镜。这个形容词先描述与双眼相关的性质，再参与 binoculars 这种仪器名称。','binocular vision；a binocular microscope；binocular viewing。','binocular 是形容词“涉及双眼”；binoculars 通常是名词“双筒望远镜”。双目设备的两条观察通道也不自动意味着每种设备都产生相同立体效果。',('The diagram explains how binocular vision helps with depth perception.','图示说明双眼视觉如何帮助感知深度。'),('The laboratory has a binocular microscope for examining small specimens.','实验室有一台用于观察小标本的双目显微镜。'),sources=[S('binocular'),K('binocular'),O('binocular')]),
E('binoculars','英 /bɪˈnɒkjələz/；美 /bɪˈnɑːkjələrz/','双筒望远镜','把两条小望远镜通道连在一起，左右眼各看一边。看鸟、远处船只或舞台时，两眼能同时观察。','由 binocular glass／glasses 等仪器表达缩略，并以复数形式 binoculars 固定下来。上游 binocular 来自“双眼的”；不是先有 binoculars 再造出双眼形容词。',EYE+[['英语 binocular glass／glasses → binoculars','供双眼使用的望远仪器；常固定用复数']],'通常说 a pair of binoculars，表示一副；直接作主语用复数：The binoculars are ...。a pair 作中心词时则用单数：This pair is ...。','a pair of binoculars；look through binoculars；carry binoculars；focus the binoculars。','telescope 是望远镜的通称，常让人想到单筒天文或远距仪器；binoculars 明确是供两眼同时使用的一副双筒望远镜。',('She used binoculars to watch the birds across the lake.','她用双筒望远镜观察湖对面的鸟。'),('This pair of binoculars is light enough to carry all day.','这副双筒望远镜很轻，带上一整天也方便。'),sources=[S('binocular'),K('binoculars'),O('binoculars')]),
E('binaural','英 /baɪˈnɔːrəl/；美 /baɪˈnɔːrəl/','双耳的；用于或模拟双耳听觉的','同一声源到左右耳的时间、强弱略有不同，大脑利用这些差别判断方向。这个词把注意力放在“两只耳朵怎样一起听”。','bin- 接拉丁 bini“两个一组” + aural“耳的、听觉的”，近代英语构词；aural 接拉丁 auris“耳”，与 oral“口头的”不同。',[['拉丁 bini；英语 aural〔接拉丁 auris〕','两个一组；耳的、听觉的']]+[['拉丁来源 bin- + 英语 aural → binaural','涉及两只耳朵的'],['现代音频用法','用双耳接收或模拟双耳听音的差异']],'binaural recording 常通过贴近左右耳位置的两个通道记录声音，让耳机播放更有方向、空间感。它不表示声音特别响，也不自动代表任何医疗效果。','binaural hearing；a binaural recording；binaural audio。','stereo 广泛指立体声、多通道的空间再现；binaural 更直接围绕两只耳朵的接收方式。两者有重叠，但不是所有 stereo 录音都按双耳方式制作。',('The museum offers a binaural recording of the old market.','博物馆提供了一段老市场的双耳录音。'),('Headphones help listeners hear the spatial details in the binaural audio.','耳机有助于听者听出这段双耳音频中的空间细节。'),sources=[S('binaural'),K('binaural'),M('binaural')]),
E('bigamy','英、美 /ˈbɪɡəmi/','重婚','一段婚姻还没有结束，又与另一个人结婚。现代常见意思的关键是婚姻重叠，不是一个人一生先后结过两次婚。','经古法语、盎格鲁法语 bigamie，接晚期／中世纪拉丁 bigamia、bigamus；bi- 是拉丁“两”，gamos 是希腊“婚姻”。属于跨语言构件结合的历史借词。',GAM,'现代常用于法律、新闻或小说中的重婚情节。中古用法还曾包括连续两次婚姻等更宽范围，因此读历史文献时不能把今天的狭义直接套回去。','a case of bigamy；accused of bigamy；bigamy charges。','remarriage 是再婚，前一段婚姻已经结束时不因“第二次”就成为 bigamy。adultery 指通奸，也不是同一个概念。',('The novel turns on the discovery of a hidden case of bigamy.','小说的关键转折是一起被隐瞒的重婚事实遭到发现。'),('The article distinguishes bigamy from remarriage after divorce.','文章区分了重婚与离婚后再婚。'),sources=[S('bigamy'),K('bigamy'),O('bigamy'),LAW]),
E('bigamist','英、美 /ˈbɪɡəmɪst/','重婚者','bigamy 是行为或状态；bigamist 则把镜头转到处于这种重叠婚姻中的那个人。','英语 bigamy 的 bigam- 词干 + -ist，表示相关行为者。bi- 在这个词里读短元音 /bɪ/，不像 bicycle 的 /baɪ/。',GAM+[['英语 bigam- + -ist → bigamist','涉及重婚的人']],'常见于犯罪报道或小说人物描述。一个人有两次已先后结束、开始的婚姻，并不能仅凭数字“两”就叫 bigamist。','an alleged bigamist；discover that someone is a bigamist。','bigamy 是重婚；bigamist 是人；bigamous 是形容词。写作时三者的句法位置不同。',('In the drama, the detective discovers that the charming stranger is a bigamist.','剧中，侦探发现那位迷人的陌生人是个重婚者。'),('The report described him as an alleged bigamist while the case was still being investigated.','案件仍在调查时，报道将他称为涉嫌重婚者。'),sources=[S('bigamist'),O('bigamist'),K('bigamist'),LAW]),
E('bigamous','英、美 /ˈbɪɡəməs/','重婚的；涉及重婚的','用来修饰婚姻、结合或相关当事人：这段关系里，有一方原有的婚姻还在存续。','英语 bigamy 的 bigam- + -ous，形成形容词。虽然拉丁早有 bigamus，现代英语词典也明确记录 bigamy + -ous 的分析，不能仅凭相似拼写就断言直接借入。',GAM+[['英语 bigam- + -ous → bigamous','重婚的；涉及重婚的']],'a bigamous marriage 指涉及重婚的婚姻安排。它是对婚姻状态的具体描述，不是泛指复杂、失败或多段恋爱。','a bigamous marriage；a bigamous relationship；a bigamous union。','bigamous 和 polygamous 相关却不完全同义：后者可讨论多配偶婚制，前者现代常突出原婚姻仍存续时另行结婚。',('The plot centres on a bigamous marriage kept secret for years.','剧情围绕一段隐瞒多年的重婚关系展开。'),('The historian explains how the word “bigamous” was used in the old records.','历史学家解释了旧档案中 bigamous 一词的用法。'),sources=[S('bigamous'),M('bigamous'),O('bigamous'),LAW]),
E('biscuit','英、美 /ˈbɪskɪt/','英式：饼干；美式：松软的小圆烤饼','词源是一种烤了两次、比较干硬的面食。今天的东西已经随地区变样：英国茶旁的脆饼，和美国餐桌上的松软烤饼，都可能叫 biscuit。','拉丁 bis“两次” + coctus“烤熟的”形成中世纪拉丁 biscoctus／biscoctum，经古法语 bescuit、中古英语多种拼写传入，后来固定为 biscuit。不是每一种现代 biscuit 都必须烤两次。',COOK+[['古法语 bescuit → 中古英语 bisquyte 等；早期现代英语 bisket','耐放的干硬面食、饼干'],['英语 biscuit','英式常指饼干；美式发展出松软烤饼义']],'英式 a chocolate biscuit 通常是一块巧克力饼干。美式 biscuits and gravy 中的 biscuits 是松软烤饼，不能想成甜脆饼干浇肉汁。字母组合 -cuit 在常见读音里是 /kɪt/。','a packet of biscuits；a chocolate biscuit；freshly baked biscuits。','cookie 在美式英语里常指甜饼干；英国的 biscuit 范围与它有重叠。美国 biscuit 的面包类用法与英国词义明显不同。',('She offered us tea and a plate of biscuits.','她给我们端来了茶和一盘饼干。'),('At the American diner, warm biscuits came with the breakfast.','在那家美式小餐馆，早餐配有热腾腾的松软烤饼。'),sources=[S('biscuit'),K('biscuit'),O('biscuit')]),
E('biscotti','英 /bɪˈskɒti/；美 /bɪˈskɑːti/','意式脆饼；常见的二次烘烤长条饼干','先把面团烤成一条，再切片回炉烤干，形成适合蘸咖啡的硬脆饼片。“两次烤”在这里仍很容易看出来。','借意大利 biscotti，是 biscotto 的复数；上游中世纪拉丁 biscoctum 接 bis“两次” + coctus“烤熟的”。它与 biscuit 同源，却走意大利语这条路线进入英语。',COOK+[['意大利 biscotto；复数 biscotti','饼干；名字承接两次烘烤的旧意'],['英语 biscotti','通常特指意式长条硬脆饼，常含坚果']],'意大利语中 biscotti 可泛指饼干；英语菜单通常指较具体的意式脆饼。意大利单数是 biscotto；英语里常把 biscotti 作为这种点心的通用名称。','almond biscotti；a plate of biscotti；dip biscotti in coffee。','biscuit 与 biscotti 是沿不同语言路线借入的同源词，不是英语 biscuit 变个复数就成了 biscotti。',('The café served almond biscotti with the espresso.','咖啡馆在浓缩咖啡旁配了杏仁意式脆饼。'),('She sliced the loaf before baking the biscotti a second time.','她先把长条面包状的饼胚切片，再把意式脆饼送去第二次烘烤。'),sources=[S('biscotti'),K('biscotti'),O('biscotti')]),
E('bipartisan','英 /ˌbaɪˈpɑːtɪzæn/；美 /ˌbaɪˈpɑːrtəzn/','两党共同支持的；跨两党合作的','原本分站两个政党阵营的人，在某件事上走到了一起。强调支持或参与跨过了党派分界。','现代英语 bi-“两” + partisan“党派的”。不是说同一个人同时属于两党，也不是由英语 part 直接加 bi- 和 -isan 现造。',PART,'a bipartisan bill 得到两党人士支持；a bipartisan committee 由两党人员组成。它不保证每位成员都赞成，也不表示方案毫无争议。','bipartisan support；a bipartisan agreement；a bipartisan committee。','nonpartisan 强调不偏向某党、没有党派立场；bipartisan 是来自两个党派的支持或参与，双方仍各有党派身份。',('The proposal gained bipartisan support in the legislature.','这项提案在议会获得了两党的支持。'),('A bipartisan committee reviewed the report.','一个由两党成员组成的委员会审查了报告。'),sources=[S('bipartisan'),K('bipartisan'),O('bipartisan')]),
E('bipartisanship','英 /ˌbaɪˈpɑːtɪzænʃɪp/；美 /ˌbaɪˈpɑːrtəznʃɪp/','两党合作；跨党派合作精神','把一份具体的“两党支持方案”放大成一种做事方式：两党愿意谈、愿意共同承担某项决定。','英语 bipartisan + -ship；-ship 把形容词所表达的合作状态变成名词，不是“船”的意思。',PART+[['英语 bipartisan + -ship → bipartisanship','两党共同参与、合作的状态或精神']],'a call for bipartisanship 是呼吁跨越党派合作；a rare moment of bipartisanship 指双方难得达成共识的时刻。它描述合作关系，不等于两党所有政策完全一致。','a spirit of bipartisanship；a call for bipartisanship；a rare display of bipartisanship。','bipartisan 修饰某项方案或团体；bipartisanship 是合作本身。compromise 是妥协，不限于两党之间。',('The joint announcement was a rare display of bipartisanship.','这份联合声明体现了难得的两党合作。'),('The debate included repeated calls for bipartisanship on the issue.','辩论中，人们多次呼吁两党在这个问题上合作。'),sources=[S('bipartisanship'),K('bipartisanship'),O('bipartisanship')]),
E('bimonthly','英、美 /ˌbaɪˈmʌnθli/','每两个月的或每两个月一次；每月两次的或每月两次','这个词里的“两”可能数月份，也可能数一个月中的次数。只看到词形，不能确定具体日程。','英语 bi- + monthly，19 世纪已记录。bi- 既可表示“每隔两个”，也可表示“两个次数”，因此实际语言中形成了两种用法。',B+[['英语 bi- + monthly → bimonthly','每两个月一次；也用于每月两次'],['日程、出版物用法','必须结合日期或上下文判明频率']],'a bimonthly magazine 可能是一年六期，也可能是每月两期。要精确安排工作，直接写 every two months 或 twice a month 更清楚，不能靠自己偏好某一种定义排除另一种。','a bimonthly report；meet bimonthly；a bimonthly publication。','biennial 通常是每两年一次；biannual 通常是一年两次。bimonthly 却真实存在双义，不能机械套用其中一个。',('The bimonthly newsletter appears in January, March, May and the other alternate months.','这份双月通讯在一月、三月、五月等隔月出版。'),('Here, “bimonthly” means twice a month, on the first and fifteenth.','这里的 bimonthly 指每月两次，分别在一号和十五号。'),sources=[S('bimonthly'),O('bimonthly'),M('biweekly'),K('bimonthly')]),
E('biweekly','英、美 /ˌbaɪˈwiːkli/','每两周的或每两周一次；每周两次的或每周两次','同样的 biweekly，两个人可能一个想到“隔周”，另一个想到“一周两回”。把日期补出来，误会就消失了。','英语 bi- 与 weekly 组合；“每两周”的结构也可分析为 bi- + week + -ly。它不是“半周”的唯一对应词，词典记录两种常见频率。',B+[['英语 bi- + weekly → biweekly','每两周一次；也可每周两次'],['现代日程用法','具体频率由上下文或明示日期决定']],'a biweekly meeting 常指隔周会议，但有时也指一周两次。薪资、出版和工作日程里都要看具体说明；fortnightly 明确表示每两周一次。','biweekly meetings；a biweekly newsletter；meet biweekly。','every two weeks 与 twice a week 没有这个歧义。semimonthly 每月两次也不等于 every two weeks，因为月份长度不同。',('Our biweekly review takes place every other Friday.','我们的双周回顾会隔一个星期五举行一次。'),('The timetable defines biweekly classes as sessions on Tuesdays and Thursdays.','课表说明，这里的 biweekly classes 是每周二、周四各一节课。'),sources=[M('biweekly'),K('biweekly'),O('biweekly')]),
E('bilateral','英、美 /ˌbaɪˈlætərəl/','双边的；双方的；两侧的','把关系看成两边：两个国家坐下来谈，或身体左右两侧都有某种情况。它告诉你涉及两方、两侧。','英语 bi-“两” + lateral“侧面的”；lateral 经法语或直接接拉丁 lateralis，来自 latus、lateris“侧面”。不是 two letters，也与 letter 无关。',LAT,'bilateral talks 通常是两国或两方会谈；bilateral symmetry 是左右对应的两侧对称。这里的“两边”不必敌对，也不要求地理上彼此相邻。','bilateral talks；a bilateral agreement；bilateral relations；bilateral symmetry。','unilateral 是单方的；multilateral 涉及多方。bipartisan 则专门强调两党，不能替代所有 bilateral 用法。',('The two countries resumed bilateral talks on transport links.','两国恢复了有关交通联系的双边会谈。'),('The diagram shows the animal’s bilateral symmetry.','图示展示了这种动物的两侧对称结构。'),sources=[S('bilateral'),K('bilateral'),O('bilateral')]),
E('bilaterally','英、美 /ˌbaɪˈlætərəli/','以双边方式；在两侧','形容动作怎么发生：两方直接商谈，或者某个结构同时出现在左右两边。','英语 bilateral + -ly，保留“涉及两边”的意义并改成副词；不是 bi- 重新修饰一个与侧面无关的 later。',LAT+[['英语 bilateral + -ly → bilaterally','由双方进行；在两侧发生或存在']],'negotiate bilaterally 是两方之间谈判；bilaterally symmetrical 说左右两侧对称。它不自动带有“两边完全一样”的意思，是否对称要靠 symmetrical 等词明确。','negotiate bilaterally；cooperate bilaterally；bilaterally symmetrical。','bilateral agreement 中用形容词修饰名词；negotiate bilaterally 中用副词修饰动作。',('The governments agreed to discuss the issue bilaterally.','两国政府同意通过双边方式讨论这个问题。'),('The pattern is arranged bilaterally around a central line.','这个图案沿中央线分布在两侧。'),sources=[K('bilaterally'),O('bilaterally'),S('bilateral')]),
E('bipolar','英 /ˌbaɪˈpəʊlə/；美 /ˌbaɪˈpoʊlər/','两极的；由两个主要力量中心构成的；双相障碍相关的','一般意思是有两个极或两端。放到不同领域，这两端可以是物理的极、国际力量中心，也可以进入特定医学名称。','英语 bi-“两” + polar“极的”，polar 经法语或中世纪拉丁接 polus“轴端、极”。医学用法是后来发展，不能用“两极”这个比喻替代真实疾病定义。',B+[['希腊 polos → 拉丁 polus → 中世纪拉丁 polaris／法语 polaire → 英语 polar','转轴、轴端 → 极的'],['英语 bi- + polar → bipolar','两极的；两个主要中心的'],['后来的精神医学用法','进入 bipolar disorder“双相障碍”这一名称']],'bipolar world 描述由两个主要力量中心主导的国际格局。bipolar disorder 涉及明显的情绪、精力和活动变化，常讨论躁狂或轻躁狂、抑郁发作；不等于普通的喜怒无常，也不是“人格分裂”。','a bipolar world；a bipolar system；bipolar disorder。','binary 强调二元分类或两状态；bipolar 强调两个极、两端。医学词义应按专业概念理解，不能因日常情绪变化就给人贴标签。',('The history lecture described a bipolar world dominated by two superpowers.','历史课描述了由两个超级大国主导的两极世界。'),('The booklet explains bipolar disorder in clear, nontechnical language.','这本小册子用清楚、少术语的语言解释双相障碍。'),sources=[S('bipolar'),K('bipolar'),O('bipolar'),'https://www.nimh.nih.gov/health/topics/bipolar-disorder']),
E('binomial','英 /baɪˈnəʊmiəl/；美 /baɪˈnoʊmiəl/','二项式；双名的；由两部分组成的物种学名','抓住“两个名称或项放在一起”。数学里是两个项，生物命名里则是属名加上第二个名称部分。','接中世纪／新拉丁 binomium、binomius，和 bi-“两”及“名称”这一构词背景相关。MW 将其接拉丁 binominis、nomen；更早形式分析另有分歧，因此不把现代英语 bi + 一个独立 nomial 当完整历史。',B+[['中世纪拉丁 binomius／binomium；后用于新拉丁','两个名称或项；常接拉丁 nomen“名字”解释'],['英语 binomial','数学的二项式；用于由两部分组成的物种学名']],'x + 3 是一个简单的二项式。binomial nomenclature 是双名法，例如物种学名由属名和种加词等第二部分组成。这里的“二”数的是项或名称部分，不是二进制数字。','a binomial expression；the binomial theorem；binomial nomenclature。','binary 是二元、二进制；binomial 是两个项或名称部分。x + 3 可以是 binomial，却不是在说这个式子用二进制表示。',('The teacher asked us to expand the square of the binomial x + 3.','老师让我们展开二项式 x + 3 的平方。'),('The guide explains why scientific species names follow a binomial system.','指南解释了为什么物种学名采用双名系统。'),sources=[M('binomial'),S('binomial'),K('binomial'),O('binomial')]),
E('bifurcate','英 /ˈbaɪfəkeɪt/；美 /ˈbaɪfərkeɪt/','分成两叉；分为两个分支','一条路走到某点变成两条，像字母 Y 的分叉。也可以把同一个流程、讨论或组织拆成两条路线。','由中世纪拉丁 bifurcare 的分词 bifurcatus 形成英语动词；再上游是拉丁 bi-“两” + furca“叉”形成 bifurcus。不是 bi + 英语 fur“毛皮”。',FUR,'道路、河流可以自行 bifurcate；组织者也可以 bifurcate a process，把流程分成两支。这是较正式的词，普通交流常说 split into two。','the road bifurcates；bifurcate into two branches；bifurcate a process。','divide 可分成任意多份；bifurcate 特别给出“两叉”的画面。separate 只说分开，不一定共享同一个起点。',('The path bifurcates just beyond the bridge.','小路在桥那头不远处分成两叉。'),('The team decided to bifurcate the process into research and implementation.','团队决定把流程分成研究和实施两条支线。'),sources=[S('bifurcate'),O('bifurcate'),K('bifurcate')]),
E('bifurcation','英 /ˌbaɪfəˈkeɪʃən/；美 /ˌbaɪfərˈkeɪʃən/','分叉；二分；分成两支的位置或过程','既能指 Y 字形中间那个岔口，也能指原来一条路线后来变成两条的变化。','英语 bifurcate 对应的 -ion 名词形式，词干用 bifurcat-；与上游中世纪拉丁 bifurcare、bifurcatus 相连。',FUR+[['英语 bifurcat- + -ion → bifurcation','分成两支的过程、状态或位置']],'the bifurcation of a road 可以是道路的分叉处。评论里的 a bifurcation of the market 则说市场逐渐分成两块走向不同的部分。更专门的数学义另有严格定义，不能仅凭“两个”概括全部。','a bifurcation point；a bifurcation in the road；the bifurcation of a process。','bifurcate 是“发生分叉”的动作；bifurcation 把岔口、分化过程作为一件事来谈。',('A sign marks the bifurcation in the trail.','一块标牌标出了小径的岔路口。'),('The report describes a bifurcation of demand into budget and premium products.','报告描述了需求逐渐分成平价产品与高端产品两块的现象。'),sources=[S('bifurcation'),M('bifurcation'),K('bifurcation'),O('bifurcation')]),
]
EXCLUDE={'bisphenol':'按用户要求暂略具体化学类别名；本页优先两、双和频率相关的通用词。'}
SHARED=['bipartite','bilingual','bilingualism','biannual','biannually','bisect','bisection']
ROOT=dict(id='C0119',meaning='两；双；两次；两个一组',core='bi- 常把后面的东西变成两个、两边或两次；bin- 与“两个一起”的 bini 有关，bis- 保留“两次”。但全词怎么用，要看形成时的历史和现在的约定。',image='两个轮子 → bicycle；两个眼睛 → binocular；两个耳朵 → binaural；两个选项 → binary；两党参与 → bipartisan；两次烤制 → biscuit／biscotti。',intro='先从轮子、眼睛、耳朵、烤饼这些具体画面入手，再看二进制、双边会谈和时间频率。这里的 bi- 不保证一律读 /baɪ/，bigamy、biscuit 等读 /bɪ/。',forms='拉丁 bi- 表“两”，bis 表“两次”，bini 表“两个一组”。binary 由拉丁 binarius 借入；binocular 有法语 binoculaire 路线；bigamy 经法语、拉丁并含希腊 gamos。bipartisan、bimonthly 等则是英语后来的组合。',branches=[['两个部件、两眼与两耳','bicycle, bifocal, binocular, binoculars, binaural'],['二元、两项与二分','binary, nonbinary, binomial, bipartite, bisect, bisection, bifurcate, bifurcation'],['两方、两党与两极','bilateral, bilaterally, bipartisan, bipartisanship, bipolar'],['两种语言','bilingual, bilingualism'],['性取向相关用法','bisexual, bisexuality'],['婚姻的历史与现代用法','bigamy, bigamist, bigamous'],['时间与次数','biennial, biennially, biannual, biannually, bimonthly, biweekly'],['烤两次的食物名称','biscuit, biscotti']],contrasts='biweekly、bimonthly 都有“每隔两个周期”和“每周期两次”两种用法，应写出具体日程。bisexual 谈性取向，nonbinary 常谈性别认同。bipolar 的医学义不等于喜怒无常。bigamy 现代常见义要求婚姻重叠，不能仅数一生结婚次数。',practice='将“两”放回具体名词：binocular vision 是双眼一起看，bilateral talks 是两方谈，bipartisan support 是两党支持。遇到 biweekly，进一步写成 every two weeks 或 twice a week。',words=[],exclude=EXCLUDE)
if __name__=='__main__':
 m=json.loads((BASE/'.cache/batch200/rewrite_vid.json').read_text());r=next(x for x in m['roots'] if x['id']==ROOT['id']);ROOT['words']=list(dict.fromkeys([w for w in r['family'] if '-' not in w and w not in EXCLUDE]+SHARED))
 already={'biennial','biennially','biannual','biannually','bilingual','bilingualism'}
 assert (set(ROOT['words'])&set(m['owned_words']))-already=={e['word'] for e in W}
 assert len(W)==len({e['word'] for e in W}) and all(len(e['examples'])>=2 and len(e['history'])>=2 for e in W)
 OUT.mkdir(parents=True,exist_ok=True)
 (OUT/'roots_batch200_vid_67.json').write_text(json.dumps([ROOT],ensure_ascii=False,indent=2));(OUT/'words_batch200_vid_67.json').write_text(json.dumps(W,ensure_ascii=False,indent=2))
 print('bi:',len(W),'words;',sum(len(e['examples']) for e in W),'examples;',len(ROOT['words']),'references')
